        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('billing.payment_term_lines') AND c.contype = 'f' AND a.attname = 'term_id'
    ) THEN
        ALTER TABLE billing.payment_term_lines ADD CONSTRAINT fk_payment_term_lines_term_id FOREIGN KEY (term_id) REFERENCES billing.payment_terms (id) NOT VALID;
