            ALTER TABLE billing.payment_term_lines VALIDATE CONSTRAINT fk_payment_term_lines_term_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_payment_term_lines_term_id left NOT VALID: stored rows of billing.payment_term_lines reference missing rows';
        END;
    END IF;
END $$;

